import {escapeHTML as e} from '/model.mjs';
let office;
export function fighterFields(field){return `<div class="panel"><h2>Fighter participation</h2><p>A fighter withdrawal is separate from an event cancellation. Keep the event scheduled when the rest of the show is going ahead.</p><div class="fields">${field('Fighter participation',['event','fighterStatus'],'text','Withdrawal adds a website notice and queues updates for this event’s paid bookings. It does not close booking or admission.',[['confirmed','Confirmed to fight'],['withdrawn','Withdrawn · event continues']])}${field('Fighter withdrawal notice',['event','fighterNotice'],'textarea','Example: Sohaib Mohammed has withdrawn due to injury and will not be fighting. The boxing event is still going ahead as scheduled.')}${field('Options after a fight-card change',['event','fighterChangePolicy'],'textarea','Explain how buyers can contact the organiser about their booking, refund eligibility or an optional transfer.')}</div></div>`;}
export function admissionFields(field){return `<div class="panel"><h2>Admission window</h2><p>Confirm these times with the venue. They control when staff may admit ticket holders.</p><div class="fields">${field('Admission opens · minutes before doors',['event','scanOpenMinutesBefore'],'number','Zero means the published doors time.')}${field('Admission closes · minutes after doors',['event','scanDurationMinutes'],'number')}</div></div>`;}
export function eventFields(draft,field){return `<div class="panel"><div class="row-heading"><h2>Event identity & customer updates</h2><button id="new-event">+ Create another event</button></div><p>Each fight night keeps its own bookings. Creating another event gives it a new reference and keeps previous tickets attached to their original event.</p><p class="muted">Event reference: ${e(draft.event.id)}</p><div class="fields">${field('Customer contact email',['event','contactEmail'],'email')}${field('Cancellation / postponement reason',['event','cancellationReason'],'textarea','Required when cancelling or postponing. Use the actual reason you want customers to receive.')}${field('Message to ticket holders',['event','customerMessage'],'textarea','Explain next steps, how to contact you and when they can expect a response.')}${field('Refund & cancellation policy',['event','refundPolicy'],'textarea','State refund eligibility and the process. Do not use blanket no-refund wording for organiser cancellations.')}${field('Transfer policy',['event','transferPolicy'],'textarea','A transfer is a customer choice. State availability and how any price difference is handled.')}${field('Welcome / thank-you message',['event','emailWelcome'],'textarea')}${field('Arrival & ID instructions',['event','arrivalInfo'],'textarea')}</div><p class="muted">Publishing changes to an existing event’s date, venue or status queues service emails for its paid bookings. An owner must publish event and ticket changes. Event records and ticket prices publish together.</p></div>`;}
export function ticketFields(draft,field){return `<div class="panel"><h2>Capacity & online availability</h2><p>These settings control this event’s online inventory after payment activation. Prices already paid remain unchanged.</p>${draft.tickets.map((t,i)=>`<div class="fields inventory-row">${field(e(t.name)+' · total capacity',['tickets',i,'capacity'],'number')}${field('Online sales',['tickets',i,'enabled'],'text','',[[false,'Disabled'],[true,'Enabled']])}</div>`).join('')}</div>`;}
export async function renderOffice(out,api){
  const token=crypto.randomUUID();out.dataset.officeView=token;
  out.innerHTML='<div class="heading"><span class="eyebrow">Ticket office</span><h1>Every night. Every booking.</h1><p>Manage event history, delivery progress and customer requests.</p></div><div id="office-body" class="panel">Loading the ticket office…</div>';
  try{office=await api('/api/admin/events');if(out.dataset.officeView!==token)return;
    out.querySelector('#office-body').outerHTML=`<div class="banner">${office.emailEnabled?'Customer email delivery is enabled.':'Email delivery awaits the verified sender connection. Notifications are recorded in the queue; they have not been sent.'} Cancelling an event closes its online booking and admission checks. Refunds and transfers require separate organiser action.</div><div class="panel"><h2>Fight-night history</h2>${office.events.length?office.events.map(item=>`<article class="office-event"><div><span class="event-badge ${item.event.status==='cancelled'?'cancelled':''}">${e(item.event.status)}</span><h3>${e(item.event.title)}</h3><p>${e(item.event.date)} · ${e(item.event.venue)}</p><small>${item.paidOrders} paid bookings · Emails: ${item.deliveries.pending} pending / ${item.deliveries.sent} sent / ${item.deliveries.failed} need review</small></div><button data-edit-event="${e(item.id)}">Edit this event</button></article>`).join(''):'<p>No event has been published to the ticket office yet. Complete the event details and publish when ready.</p>'}</div><div class="panel"><h2>Refund & transfer requests</h2><p>A customer request is a recorded preference. Marking it resolved does not move money or create replacement tickets. Record the actual provider action in the organiser note.</p>${office.requests.length?office.requests.map(r=>`<form class="request-form" data-request-id="${e(r.id)}"><h3>${e(r.kind)} request · ${e(r.event)}</h3><p>${e(r.email)}<br>Order ${e(r.orderId)}</p><blockquote>${e(r.message||'No additional message')}</blockquote><div class="fields"><label class="field"><span>Progress</span><select name="status">${[['requested','New request'],['in_progress','In progress'],['resolved','Resolved']].map(([v,l])=>`<option value="${v}" ${v===r.status?'selected':''}>${l}</option>`).join('')}</select></label><label class="field full"><span>Private organiser note</span><textarea name="note" maxlength="2000">${e(r.note)}</textarea></label></div><button ${office.role!=='owner'?'disabled':''}>Save request progress</button></form>`).join(''):'<div class="empty">Customer requests will appear here. Buyers can submit them through their private ticket page.</div>'}</div>`;
  }catch(error){if(out.dataset.officeView===token)out.querySelector('#office-body').textContent=error.message;}
}
export function selectEvent(id,draft){const item=office?.events.find(x=>x.id===id);if(!item)throw Error('Reload the ticket office before selecting this event.');draft.event={...item.event};draft.tickets=item.event.ticketOptions||item.tickets||draft.tickets.map(t=>({...t,id:crypto.randomUUID(),enabled:false}));if(item.event.posterURL)draft.media['b075c7a3-0007-49c9-ab43-9ce1fa01ba54.jpeg'].url=item.event.posterURL;}
export function newEvent(draft){draft.event={...draft.event,id:crypto.randomUUID(),title:'New boxing event',status:'draft',cancellationReason:'',customerMessage:'',fighterStatus:'confirmed',fighterNotice:''};draft.tickets=draft.tickets.map(t=>({...t,id:crypto.randomUUID(),enabled:false}));}
